import {DuckDBClient} from "@observablehq/duckdb"







RPG_URL = "https://minio.lab.sspcloud.fr/lgaliana/data/geodata-days/rpg_pac_2024_62_comm_v11.parquet"







db = DuckDBClient.of({ dico: dico })







// Réchauffe le fetch réseau + le cache DuckDB-wasm du parquet dès le
// chargement du deck, pour que le premier "Tester en live" mesure le temps
// de requête et non le temps de téléchargement du fichier. Sert aussi à
// afficher le nombre de lignes scannées en entrée des requêtes.
warmupRPG = db.query(`SELECT COUNT(*) AS n_input FROM read_parquet('${RPG_URL}') WHERE code_cultu IS NOT NULL`)







totalInputRows = Number(Array.from(warmupRPG)[0].n_input)







function truncateLabel(text, maxLen = 42) {
  const s = String(text ?? "");
  return s.length &gt; maxLen ? s.slice(0, maxLen - 1) + "…" : s;
}







function toggleInput(defaultValue = false) {
  const input = html`&lt;input type="checkbox" ${defaultValue ? "checked" : ""}&gt;`;
  const label = html`&lt;label style="cursor: pointer; user-select: none; font-size: 0.9em;"&gt;${input} &lt;span&gt;SQL ⇄ graphique&lt;/span&gt;&lt;/label&gt;`;
  label.value = input.checked;
  input.oninput = () =&gt; {
    label.value = input.checked;
    label.dispatchEvent(new CustomEvent("input"));
  };
  return label;
}







function sqlOrPlot(toggle, sql, plot) {
  const container = html`&lt;div&gt;&lt;/div&gt;`;
  function render() {
    container.replaceChildren(toggle.value ? html`&lt;pre&gt;&lt;code&gt;${sql}&lt;/code&gt;&lt;/pre&gt;` : plot);
  }
  render();
  toggle.addEventListener("input", render);
  return container;
}







function runLiveButton(label = "Tester en live") {
  const btn = html`&lt;button type="button" class="run-live-btn" aria-label="${label}" title="${label}"&gt;
    &lt;svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"&gt;&lt;path d="M8 5v14l11-7z"/&gt;&lt;/svg&gt;
  &lt;/button&gt;`;
  btn.value = null;
  btn.onclick = () =&gt; {
    btn.value = Date.now();
    btn.dispatchEvent(new CustomEvent("input"));
  };
  return btn;
}







function searchInput(placeholder = "Rechercher…") {
  const input = html`&lt;input type="search" class="testlive-search-input" placeholder="${placeholder}"&gt;`;
  input.value = "";
  return input;
}







function frInt(n) {
  return Number(n).toLocaleString("fr-FR");
}







function frNumber(n, decimals = 0) {
  return Number(n).toLocaleString("fr-FR", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  });
}







function barCell(share, color = "#4758AB") {
  const pct = share * 100;
  return html`&lt;div class="bar-track"&gt;&lt;div class="bar-fill" style="width:${pct}%; background:${color}"&gt;&lt;/div&gt;&lt;span class="bar-label"&gt;${pct.toFixed(1)}%&lt;/span&gt;&lt;/div&gt;`;
}







// Widget autonome "bouton play + timing + recherche + tableau", pour
// dupliquer facilement une démo "Tester en live" avec une autre requête.
// mapRow convertit chaque ligne Arrow renvoyée par db.query en objet JS
// simple ; valueField est la colonne numérique utilisée pour la part (%)
// affichée dans la colonne "part". extraBar ajoute une 2e colonne barre
// (une autre couleur) sur un second champ numérique, pour comparer d'un
// coup d'oeil deux proportions (ex : part des parcelles vs part de la
// surface).
function liveQueryDemo({
  sql,
  mapRow,
  valueField,
  searchFields,
  columns,
  header,
  width,
  valueFormat = frInt,
  searchPlaceholder = "🔍 Rechercher…",
  buttonLabel = "Tester en live",
  barColor = "#4758AB",
  extraBar = null,
  format = {},
  align = {}
}) {
  const btn = runLiveButton(buttonLabel);
  const search = searchInput(searchPlaceholder);
  search.style.display = "none";
  const statusBox = html`&lt;div&gt;&lt;/div&gt;`;
  const resultsBox = html`&lt;div&gt;&lt;/div&gt;`;
  let currentRows = null;

  function renderStatus(elapsed_ms) {
    statusBox.replaceChildren(
      elapsed_ms == null
        ? html`&lt;p class="testlive-placeholder"&gt;Lancer la démo live.&lt;/p&gt;`
        : html`&lt;p class="testlive-timing"&gt;⏱️ Temps d'exécution : &lt;strong&gt;${elapsed_ms.toFixed(0)} ms&lt;/strong&gt; · ${totalInputRows.toLocaleString("fr-FR")} → ${currentRows.length} lignes&lt;/p&gt;`
    );
  }

  function renderTable() {
    const q = search.value.trim().toLowerCase();
    const rows = !q
      ? currentRows
      : currentRows.filter((r) =&gt; searchFields.map((f) =&gt; r[f]).join(" ").toLowerCase().includes(q));
    const extraFormat = extraBar
      ? { [extraBar.key]: (v) =&gt; barCell(v, extraBar.color ?? barColor) }
      : {};
    resultsBox.replaceChildren(
      html`&lt;div class="testlive-results"&gt;${Inputs.table(rows, {
        columns,
        header,
        width,
        align: { [valueField]: "right", ...align },
        format: { [valueField]: valueFormat, part: (v) =&gt; barCell(v, barColor), ...extraFormat, ...format },
        layout: "fixed",
        rows: 10
      })}&lt;/div&gt;`
    );
  }

  renderStatus(null);

  search.addEventListener("input", renderTable);

  btn.addEventListener("input", async () =&gt; {
    const t0 = performance.now();
    const raw = await db.query(sql);
    const rows = Array.from(raw, mapRow);
    const total = d3.sum(rows, (d) =&gt; d[valueField]);
    let withParts = rows.map((d) =&gt; ({ ...d, part: total &gt; 0 ? d[valueField] / total : 0 }));
    if (extraBar) {
      const totalExtra = d3.sum(rows, (d) =&gt; d[extraBar.field]);
      withParts = withParts.map((d) =&gt; ({
        ...d,
        [extraBar.key]: totalExtra &gt; 0 ? d[extraBar.field] / totalExtra : 0
      }));
    }
    currentRows = withParts;
    renderStatus(performance.now() - t0);
    search.value = "";
    search.style.display = "";
    renderTable();
  });

  return html`&lt;div class="testlive-widget"&gt;${btn}${statusBox}${search}${resultsBox}&lt;/div&gt;`;
}







sqlTestLive = `
SELECT
    r.code_cultu,
    COALESCE(d.nom_culture, r.code_cultu) AS nom_culture,
    COALESCE(d.nom_chapitre, 'Non classé') AS nom_chapitre,
    COUNT(*) AS n
FROM read_parquet('${RPG_URL}') r
LEFT JOIN dico d ON r.code_cultu = d.code_culture
WHERE r.code_cultu IS NOT NULL
GROUP BY 1, 2, 3
ORDER BY n DESC
`







liveQueryDemo({
  sql: sqlTestLive,
  mapRow: (d) =&gt; ({
    code_cultu: d.code_cultu,
    nom_culture: d.nom_culture,
    nom_chapitre: d.nom_chapitre,
    n: Number(d.n)
  }),
  valueField: "n",
  searchFields: ["nom_culture", "nom_chapitre", "code_cultu"],
  columns: ["nom_culture", "nom_chapitre", "n", "part"],
  header: {
    nom_culture: "Culture",
    nom_chapitre: "Famille",
    n: "Parcelles",
    part: "Proportion"
  },
  width: { nom_culture: 200, nom_chapitre: 200, n: 90, part: 160 },
  searchPlaceholder: "🔍 Rechercher une culture ou une famille…"
})

Démo live 3

// Résout code_cultu -&gt; {nom_culture, nom_chapitre, ...} pour les GeoJSON
// précalculés (data/communes/*.geojson, data/parcelles-full.geojson), qui ne
// stockent que le code (`k`) pour rester légers. Utilisé par
// demo/explorer-commune.qmd et demo/culture-highlight.qmd.
dicoByCode = new Map(dico.map((d) =&gt; [d.code_culture, d]))







// Import MapLibre partagé par les deux slides carte du deck
// (demo/explorer-commune.qmd et demo/culture-highlight.qmd), qui créent
// chacune leur propre instance de carte à partir de ce même module.
maplibregl = require("maplibre-gl@5")







// Géométries des parcelles précalculées par commune (voir
// scripts/generate_quarto_commune_data.py) : DuckDB-wasm dans le navigateur
// ne parvient pas à charger l'extension spatiale de façon fiable avec le
// DuckDBClient bundlé (version trop ancienne côté Observable), donc la
// reprojection Lambert-93 -&gt; WGS84 est faite une fois, au moment du rendu.
communeSlugs = fetch("data/communes/index.json").then((r) =&gt; r.json())







viewof communeSel = Inputs.select(Object.keys(communeSlugs).sort(), { label: "Commune", value: "Arras" })







familyColor = d3.scaleOrdinal(
  [...new Set(dico.map((d) =&gt; d.nom_chapitre))].sort(),
  d3.schemeTableau10.concat(d3.schemeSet3)
)







// Parcourt récursivement un tableau de coordonnées GeoJSON (Polygon ou
// MultiPolygon) pour calculer une bounding box, sans dépendance à turf.
function geojsonBounds(fc) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  function visit(coords) {
    if (typeof coords[0] === "number") {
      const [x, y] = coords;
      if (x &lt; minX) minX = x;
      if (x &gt; maxX) maxX = x;
      if (y &lt; minY) minY = y;
      if (y &gt; maxY) maxY = y;
    } else {
      coords.forEach(visit);
    }
  }
  fc.features.forEach((f) =&gt; visit(f.geometry.coordinates));
  return [[minX, minY], [maxX, maxY]];
}









mapDiv = {
  const div = document.createElement("div");
  div.style.height = "440px";
  div.style.borderRadius = "8px";
  div.style.zIndex = "0";
  return div;
}







map = {
  const m = new maplibregl.Map({
    container: mapDiv,
    style: {
      version: 8,
      sources: {
        osm: {
          type: "raster",
          tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
          tileSize: 256,
          attribution: "&copy; OpenStreetMap contributors"
        }
      },
      layers: [{ id: "osm", type: "raster", source: "osm" }]
    },
    center: [2.5, 50.4],
    zoom: 9
  });
  m.addControl(new maplibregl.NavigationControl());
  return m;
}







// Résolu une fois le style de base chargé : source + calques des parcelles,
// et le mouseover (popup) sur la couche de remplissage.
mapReady = new Promise((resolve) =&gt; {
  map.on("load", () =&gt; {
    map.addSource("parcels", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
    map.addLayer({
      id: "parcels-fill",
      type: "fill",
      source: "parcels",
      paint: { "fill-color": ["get", "color"], "fill-opacity": 0.75 }
    });
    map.addLayer({
      id: "parcels-line",
      type: "line",
      source: "parcels",
      paint: { "line-color": "#20201d", "line-width": 0.4, "line-opacity": 0.6 }
    });

    const popup = new maplibregl.Popup({ closeButton: false });
    map.on("mousemove", "parcels-fill", (e) =&gt; {
      map.getCanvas().style.cursor = "pointer";
      const f = e.features[0];
      popup
        .setLngLat(e.lngLat)
        .setHTML(`&lt;strong&gt;${f.properties.nom_culture}&lt;/strong&gt;&lt;br&gt;${Number(f.properties.surface_ha).toFixed(2)} ha`)
        .addTo(map);
    });
    map.on("mouseleave", "parcels-fill", () =&gt; {
      map.getCanvas().style.cursor = "";
      popup.remove();
    });

    map.resize();
    resolve();
  });
})







// La géométrie ne peut pas venir d'un simple GROUP BY : dessiner un contour
// de parcelle nécessite la forme réelle, donc le fichier précalculé
// (communeSlugs / data/communes/*.geojson) reste la seule source possible
// ici, indépendamment du barplot ci-contre qui n'en a lui pas besoin.
communeGeo = {
  const slug = communeSlugs[communeSel];
  const fc = await fetch(`data/communes/${slug}.geojson`).then((r) =&gt; r.json());
  return {
    type: "FeatureCollection",
    features: fc.features.map((f) =&gt; {
      const meta = dicoByCode.get(f.properties.k);
      const nom_chapitre = meta?.nom_chapitre ?? "Non classé";
      return {
        type: "Feature",
        geometry: f.geometry,
        properties: {
          nom_culture: meta?.nom_culture ?? f.properties.k,
          nom_chapitre,
          surface_ha: f.properties.s,
          color: familyColor(nom_chapitre)
        }
      };
    })
  };
}







// Met à jour la source à chaque changement de commune et recadre la carte.
updateMap = {
  await mapReady;
  map.getSource("parcels").setData(communeGeo);
  const bounds = geojsonBounds(communeGeo);
  if (Number.isFinite(bounds[0][0])) {
    map.fitBounds(bounds, { padding: 24, maxZoom: 15, duration: 300 });
  }
  return true;
}







{
  updateMap;
  return html`&lt;p class="testlive-timing"&gt;⏱️ Requête SQL : &lt;strong&gt;${communeStats.elapsed_ms.toFixed(0)} ms&lt;/strong&gt; · ${communeGeo.features.length} parcelles affichées — ${communeSel}&lt;/p&gt;`;
}








// Contrairement à la géométrie de la carte, ceci n'a pas besoin de spatial :
// juste un filtre par commune + GROUP BY culture, comme les autres slides
// "Test live" du deck — donc requête SQL live, pas de fichier précalculé.
sqlCommuneStats = (commune) =&gt; `
SELECT
    COALESCE(d.nom_culture, r.code_cultu) AS nom_culture,
    COALESCE(d.nom_chapitre, 'Non classé') AS nom_chapitre,
    COUNT(*) AS n,
    SUM(r.area) / 10000 AS surface_ha
FROM read_parquet('${RPG_URL}') r
LEFT JOIN dico d ON r.code_cultu = d.code_culture
WHERE r.nom_officiel = '${commune.replace(/'/g, "''")}'
GROUP BY 1, 2
ORDER BY surface_ha DESC
`







communeStats = {
  const t0 = performance.now();
  const raw = await db.query(sqlCommuneStats(communeSel));
  const rows = Array.from(raw, (d) =&gt; ({
    nom_culture: d.nom_culture,
    nom_chapitre: d.nom_chapitre,
    n: Number(d.n),
    surface_ha: Number(d.surface_ha)
  }));
  return { rows, barRows: rows.slice(0, 12), elapsed_ms: performance.now() - t0 };
}







Plot.plot({
  marginLeft: 220,
  width: 480,
  height: 440,
  x: { label: "Surface (ha)" },
  y: { label: null, tickFormat: truncateLabel },
  marks: [
    Plot.barX(communeStats.barRows, {
      y: "nom_culture",
      x: "surface_ha",
      fill: "#008A25",
      sort: { y: "-x" }
    })
  ]
})

Des calculs fluides

// Part de surface par culture (colonne `area`, pas de géométrie/extension
// spatiale nécessaire ici : requête légère, indépendante du chargement de
// la carte ci-dessous).
sqlCultureShare = `
SELECT
    COALESCE(d.nom_culture, r.code_cultu) AS nom_culture,
    SUM(r.area) / 10000 AS surface_ha
FROM read_parquet('${RPG_URL}') r
LEFT JOIN dico d ON r.code_cultu = d.code_culture
WHERE r.code_cultu IS NOT NULL
GROUP BY 1
ORDER BY surface_ha DESC
`







cultureShareData = Array.from(await db.query(sqlCultureShare), (d) =&gt; ({
  nom_culture: d.nom_culture,
  surface_ha: Number(d.surface_ha)
}))







AUTRES_LABEL = "Autres cultures (&lt; 1 % chacune)"







// Cultures représentant au moins 1% de la surface du département, triées
// par importance décroissante (déjà l'ordre de sqlCultureShare) ; le reste
// (nombreuses cultures marginales) est regroupé dans une catégorie "Autres"
// pour garder un sélecteur lisible.
topCultures = {
  const total = d3.sum(cultureShareData, (d) =&gt; d.surface_ha);
  return cultureShareData.filter((d) =&gt; d.surface_ha / total &gt;= 0.01).map((d) =&gt; d.nom_culture);
}







topCultureSet = new Set(topCultures)







cultureList = topCultures.length &lt; cultureShareData.length ? [...topCultures, AUTRES_LABEL] : topCultures









mapAllDiv = {
  const div = document.createElement("div");
  div.style.height = "440px";
  div.style.borderRadius = "8px";
  div.style.zIndex = "0";
  return div;
}







// mapAll est une carte MapLibre distincte de `map` (slide "Explorer par
// commune") : sources/layers/ids séparés (parcels-all-*) pour ne pas
// interférer avec l'autre slide, mais le même import `maplibregl`
// (demo/common.qmd) est réutilisé.
mapAll = {
  const m = new maplibregl.Map({
    container: mapAllDiv,
    style: {
      version: 8,
      sources: {
        osm: {
          type: "raster",
          tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
          tileSize: 256,
          attribution: "&copy; OpenStreetMap contributors"
        }
      },
      layers: [{ id: "osm", type: "raster", source: "osm" }]
    },
    // Emprise fixe du Pas-de-Calais (mêmes bornes que la carte brute du site
    // Observable), pas besoin de recadrer dynamiquement ici.
    bounds: [[1.5629901, 50.0198391], [3.188217, 51.0068167]]
  });
  m.addControl(new maplibregl.NavigationControl());
  return m;
}







mapAllReady = new Promise((resolve) =&gt; {
  mapAll.on("load", () =&gt; {
    mapAll.addSource("parcels-all", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
    mapAll.addLayer({
      id: "parcels-all-fill",
      type: "fill",
      source: "parcels-all",
      paint: { "fill-color": "#c9c9c2", "fill-opacity": 0.25 }
    });
    mapAll.addLayer({
      id: "parcels-all-line",
      type: "line",
      source: "parcels-all",
      paint: { "line-color": "#20201d", "line-width": 0.15, "line-opacity": 0.25 }
    });

    const popup = new maplibregl.Popup({ closeButton: false });
    mapAll.on("mousemove", "parcels-all-fill", (e) =&gt; {
      mapAll.getCanvas().style.cursor = "pointer";
      const f = e.features[0];
      popup
        .setLngLat(e.lngLat)
        .setHTML(`&lt;strong&gt;${f.properties.nom_culture}&lt;/strong&gt;&lt;br&gt;${Number(f.properties.surface_ha).toFixed(2)} ha`)
        .addTo(mapAll);
    });
    mapAll.on("mouseleave", "parcels-all-fill", () =&gt; {
      mapAll.getCanvas().style.cursor = "";
      popup.remove();
    });

    mapAll.resize();
    resolve();
  });
})







// Chargement complet (une seule fois, dès que la carte est prête) : la
// géométrie de tout le département — précalculée (voir
// scripts/generate_quarto_full_parcels.py ; même raison qu'"Explorer par
// commune" : l'extension spatiale ne se charge pas de façon fiable dans
// DuckDB-wasm avec le DuckDBClient bundlé) — est récupérée puis posée sur
// la source MapLibre. Ensuite, changer la culture sélectionnée (viewof
// cultureSel, colonne de droite) ne relance aucun fetch : c'est juste un
// repaint MapLibre sur les données déjà en mémoire dans le navigateur — le
// "calcul fluide" de ce slide.
allParcelsData = {
  await mapAllReady;
  const t0 = performance.now();
  const fc = await fetch("data/parcelles-full.geojson").then((r) =&gt; r.json());
  const rows = fc.features.map((f) =&gt; {
    const meta = dicoByCode.get(f.properties.k);
    return {
      code_cultu: f.properties.k,
      nom_culture: meta?.nom_culture ?? f.properties.k,
      surface_ha: f.properties.s,
      geometry: f.geometry
    };
  });
  const geojson = {
    type: "FeatureCollection",
    features: rows.map((r) =&gt; ({
      type: "Feature",
      geometry: r.geometry,
      properties: { code_cultu: r.code_cultu, nom_culture: r.nom_culture, surface_ha: r.surface_ha }
    }))
  };
  mapAll.getSource("parcels-all").setData(geojson);
  return { rows, geojson, elapsed_ms: performance.now() - t0 };
}







{
  if (allParcelsData == null) {
    return html`&lt;p class="testlive-placeholder"&gt;Chargement des ${totalInputRows.toLocaleString("fr-FR")} parcelles du département…&lt;/p&gt;`;
  }
  // Le timing affiché ici est celui du dernier surlignage (updateAllMapHighlight),
  // pas celui du chargement des données : c'est la partie "fluide" qu'on veut
  // montrer — changer de culture ne relance ni fetch ni requête.
  return html`&lt;p class="testlive-timing"&gt;⏱️ Surlignage recalculé en &lt;strong&gt;${updateAllMapHighlight.toFixed(2)} ms&lt;/strong&gt; · ${allParcelsData.rows.length.toLocaleString("fr-FR")} parcelles en mémoire&lt;/p&gt;`;
}








viewof cultureSel = Inputs.select(cultureList, { label: "Culture à surligner", value: "Blé tendre" })







updateAllMapHighlight = {
  await mapAllReady;
  if (allParcelsData == null) return 0;
  const t0 = performance.now();
  const isSelected = cultureSel === AUTRES_LABEL
    ? ["!", ["in", ["get", "nom_culture"], ["literal", topCultures]]]
    : ["==", ["get", "nom_culture"], cultureSel];
  mapAll.setPaintProperty("parcels-all-fill", "fill-color", ["case", isSelected, "#ec6842", "#c9c9c2"]);
  mapAll.setPaintProperty("parcels-all-fill", "fill-opacity", ["case", isSelected, 0.85, 0.15]);
  mapAll.setPaintProperty("parcels-all-line", "line-color", ["case", isSelected, "#7a2f10", "#20201d"]);
  mapAll.setPaintProperty("parcels-all-line", "line-opacity", ["case", isSelected, 0.9, 0.15]);
  return performance.now() - t0;
}







selectedCultureStats = {
  updateAllMapHighlight;
  if (allParcelsData == null) return null;
  const rows = allParcelsData.rows;
  const totalSurface = d3.sum(rows, (d) =&gt; d.surface_ha);
  const selRows = cultureSel === AUTRES_LABEL
    ? rows.filter((d) =&gt; !topCultureSet.has(d.nom_culture))
    : rows.filter((d) =&gt; d.nom_culture === cultureSel);
  const surface = d3.sum(selRows, (d) =&gt; d.surface_ha);
  return { n: selRows.length, surface, part: totalSurface &gt; 0 ? surface / totalSurface : 0 };
}







{
  if (selectedCultureStats == null) {
    return html`&lt;p class="testlive-placeholder"&gt;En attente du chargement de la carte…&lt;/p&gt;`;
  }
  const s = selectedCultureStats;
  return html`&lt;div class="highlight-stats"&gt;
    &lt;div class="stat-value"&gt;${s.n.toLocaleString("fr-FR")}&lt;/div&gt;
    &lt;div class="stat-label"&gt;parcelles de « ${cultureSel} »&lt;/div&gt;
    &lt;div class="stat-value"&gt;${frNumber(s.surface, 0)} ha&lt;/div&gt;
    &lt;div class="stat-label"&gt;soit ${(s.part * 100).toFixed(1)} % de la surface du département&lt;/div&gt;
  &lt;/div&gt;`;
}
